-- Study Abroad country content, BATCH 30: Mauritania, Monaco, Rep. of Congo, San Marino, Sao Tome, Somalia, Suriname, Syria, Timor-Leste, Vatican City, Yemen.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('mauritania', 'monaco', 'republic-of-the-congo', 'san-marino', 'sao-tome-and-principe', 'somalia', 'suriname', 'syria', 'timor-leste', 'vatican-city', 'yemen'));
UPDATE countries SET why_title = 'Why study in Mauritania?', why_body = '<p>Mauritania has public universities in Nouakchott teaching in Arabic and French at very low fees, with limited information for foreign applicants.<ul><li>Arabic and French teaching</li><li>University of Nouakchott Al-Asriya</li><li>Very low tuition</li><li>Desert and Sahel context</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>One guide says an e-visa must be approved online before travel since 5 January 2025 and no separate student visa is described; another describes a student visa category. Confirm with the embassy.</p><ul><li>Admission letter from the university</li><li>E-visa approved online before travel (guide)</li><li>Confirm the entry route with the Mauritanian embassy or consulate</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Mauritanian embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>The university does not publish an admission procedure or fees for foreign applicants.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official fees were found.</p><ul><li>A third-party listing shows about US$211 a year for international and domestic students; unverified</li><li>The 2026-27 scholarships found are bilateral PhD places for Algerian students</li><li>Living costs: about US$250-$450 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a baccalauréat or equivalent</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Arabic or French proof depending on programme</li></ul>' WHERE slug = 'mauritania';
UPDATE countries SET why_title = 'Why study in Monaco?', why_body = '<p>Monaco offers English-taught business, luxury, finance and sports management degrees at the International University of Monaco, at high fees on the French Riviera.<ul><li>English-taught business degrees</li><li>International University of Monaco (AACSB accredited)</li><li>Luxury, finance and sports management programmes</li><li>High living costs</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Monaco has no visa service of its own; non-EEA students apply through French consulates. IUM describes a long-stay visa (type D) valid three months, then a Monegasque residence permit applied for within the first two months for students living in Monaco. Students who do not live in Monaco do not need a Monaco student visa.</p><ul><li>Admission letter from IUM</li><li>Funds: the amount is set by the Monaco bank giving the reference and is very high without family or business in Monaco</li><li>First-year temporary card fee reported at EUR 80 (September 2026), renewal EUR 40</li><li>Plan early because residency processing capacity is tight</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official IUM Student Services and MonServicePublic site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to IUM.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Motivation letter and CV for master''s programmes</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>IUM publishes its tuition fees.</p><ul><li>BBA (January 2027 intake): EUR 14,825 in year 1, EUR 14,675 in years 2 and 3; Honors Track EUR 15,775 / EUR 14,375</li><li>MSc programmes: about EUR 16,450-31,875 depending on specialisation and intake (aggregator)</li><li>MBA: about EUR 41,900 (AACSB listing)</li><li>Extras: Student Association fee EUR 190 a year; IUM for Life fee EUR 675; 5% supplement on the seven-instalment plan</li><li>Living costs: very high (estimate: EUR 2,000+ a month)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate or baccalauréat</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof (IELTS / TOEFL)</li></ul>' WHERE slug = 'monaco';
UPDATE countries SET why_title = 'Why study in the Republic of the Congo?', why_body = '<p>The Republic of the Congo has French-taught universities in Brazzaville, led by Marien Ngouabi University, at low fees.<ul><li>French-medium teaching</li><li>Marien Ngouabi University</li><li>Low tuition</li><li>Oil and forestry sectors</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Apply for a student visa at the nearest embassy or consulate after admission (secondary guides); no official 2026 checklist was found.</p><ul><li>Admission letter from the university</li><li>Admission is selective, based on entrance examinations (aggregator)</li><li>Check the embassy for current fees and documents</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Congolese embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Contact the university registrar (scolarité); online pre-registration dates reported for 2026-27 may refer to another university, so verify.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official international tuition schedule was found.</p><ul><li>Country-wide public university estimate: US$80-$330 a year; uniRank shows a US$0-$999 band (unreliable)</li><li>UMNG government scholarships are for Congolese citizens only</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a baccalauréat or equivalent</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'republic-of-the-congo';
UPDATE countries SET why_title = 'Why study in San Marino?', why_body = '<p>San Marino offers Italian- and English-taught degrees at the University of the Republic of San Marino in a tiny European microstate surrounded by Italy.<ul><li>Small, close-knit university</li><li>European setting</li><li>Erasmus and exchange partnerships</li><li>Italian-speaking environment</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Exchange students from inside and outside the Schengen area apply for a <strong>Residence Permit for Study Purposes</strong> at the Gendarmerie (Foreigners Office). Italian students and foreign students legally residing in Italy are exempt under reciprocity agreements.</p><ul><li>Admission or exchange acceptance at UNIRSM</li><li>Collect the university badge, enrolment certificate and SMaC card at the Student Office within two days of arrival</li><li>Visa and immigration help comes only after admission</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official The Gendarmerie Foreigners Office and the UNIRSM International Office site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Exchange deadlines: 30 May for the fall semester and 30 November for the spring semester, by email to the International Office.</p><ul><li>Academic transcripts and certificates</li><li>Italian or English proof depending on programme</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Exchange nomination from the home university</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No standard degree tuition schedule was found.</p><ul><li>Students who have not paid tuition cannot enrol in the following year</li><li>UNIRSM offers 45 partial scholarships for 2026/27 covering the third instalment of the enrolment fee</li><li>Pain medicine course: EUR 1,000 in two instalments</li><li>Least developed country students may get exemptions (commercial source; verify with UNIRSM)</li><li>Living costs: about EUR 900-1,500 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school diploma</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Italian or English proof depending on programme</li></ul>' WHERE slug = 'san-marino';
UPDATE countries SET why_title = 'Why study in São Tomé and Príncipe?', why_body = '<p>São Tomé and Príncipe has a small Portuguese-taught higher-education system with the University of São Tomé and Príncipe and a private Lusíada university.<ul><li>Portuguese-medium teaching</li><li>University of São Tomé and Príncipe (USTP, 2014)</li><li>Universidade Lusíada de São Tomé e Príncipe</li><li>Island and ocean context</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A student visa is required; apply at the nearest embassy or consulate after admission. The country does not publish a single detailed student visa manual.</p><ul><li>Admission letter from the institution</li><li>Health insurance may be required</li><li>Confirm details with the issuing embassy</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official São Tomé and Príncipe embassy and your institution site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>USTP''s international admission round normally runs between January and August each year; the minimum entry requirement is the Certidão de 12ª Classe or equivalent.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official tuition schedule was found.</p><ul><li>Aggregator: public universities US$200-$800 a year; living costs US$300-$500 a month (unverified)</li><li>Ask USTP for current fees</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a Certidão de 12ª Classe or equivalent</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Portuguese proof for Portuguese-taught programmes</li></ul>' WHERE slug = 'sao-tome-and-principe';
UPDATE countries SET why_title = 'Why study in Somalia?', why_body = '<p>Somalia has several universities such as SIMAD, Mogadishu University and Somali National University, but security conditions are very severe.<ul><li>English and Somali instruction</li><li>SIMAD University, Mogadishu University, Somali National University</li><li>Low tuition at some universities</li><li>Check current conditions</li></ul></p><p>The UK advises against all travel to most of Somalia including Mogadishu (18 October 2026) and the US lists Level 4, Do Not Travel (May 2026). This page is informational only and does not recommend travel.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Since 1 September 2025 all foreign nationals travelling to Somalia must apply online for an E-Visa through the Electronic Travel Authorisation System (etas.gov.so). No separate student route is published; other sources say a student visa is required.</p><ul><li>Admission letter from the university</li><li>Complete the online travel authorisation before travel</li><li>No student work rights or post-study route published</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Somali Immigration and Citizenship Agency and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Figures conflict.</p><ul><li>Somali National University: undergraduate programmes listed as tuition-free in 2026, with administrative charges of US$50-$125 and US$350 for the compulsory English foundation programme</li><li>SIMAD: US$220 (one listing) or about US$1,000 a year (aggregator); no official schedule found</li><li>Mogadishu University: no fee found</li><li>Living costs: not estimated because of conditions</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English or Somali proof depending on programme</li></ul>' WHERE slug = 'somalia';
UPDATE countries SET why_title = 'Why study in Suriname?', why_body = '<p>Suriname offers Dutch-taught degrees at Anton de Kom University in Paramaribo, on the northern coast of South America.<ul><li>Dutch-medium teaching</li><li>Anton de Kom University of Suriname</li><li>Caribbean and South American links</li><li>Rainforest and agriculture context</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>The student permit process was not found; contact AdeKUS admissions and the Surinamese immigration authority.</p><ul><li>Admission letter from the university</li><li>Check the immigration authority for the permit</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Surinamese immigration authority and AdeKUS site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>For 2026-27 the main window for new bachelor''s students ran 4-31 August 2026; the late window (19-30 October 2026) has closed. Ask the Bureau Studentenzaken about qualification equivalence before paying.</p><ul><li>Academic transcripts and certificates</li><li>VWO diploma or equivalent for bachelor''s programmes</li><li>Dutch language proof</li><li>Passport copy and photographs</li><li>Check the equivalence of your qualification</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>The registration fee and tuition conflict across sources.</p><ul><li>AdeKUS registration fee for 2026-27: SRD 5,000; some master''s programmes also charge tuition</li><li>Aggregator: SRD 5,000-15,000 a year; free-apply lists about US$1,750 (third party)</li><li>No scholarship for international students found</li><li>Living costs: about US$400-$700 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a VWO diploma or equivalent</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Dutch proof for Dutch-taught programmes</li></ul>' WHERE slug = 'suriname';
UPDATE countries SET why_title = 'Why study in Syria?', why_body = '<p>Syria has long-established universities such as Damascus University, but security conditions are severe.<ul><li>Damascus University (founded 1923)</li><li>Arabic-medium teaching</li><li>Syrian Virtual University for online study</li><li>Check current conditions</li></ul></p><p>A guide summarising UK advice reports a very high kidnap threat that names students, bomb attacks in central Damascus in July 2026, and landmines; Canada advises against all travel. Check official advice. This page does not recommend travel.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A student visa is required; apply at the nearest Syrian embassy or consulate after acceptance (guide).</p><ul><li>Admission letter from the university</li><li>Ask about foreign certificate equivalence and tuition classification</li><li>A university''s domestic recognition does not guarantee foreign recognition</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Syrian embassy and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Apply directly to each university; confirm the process for foreign certificates.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Figures conflict.</p><ul><li>2026-27 guide: public universities charge foreign students US$2,000-$5,000 a year plus a one-off US$1,000 registration fee</li><li>Another guide: SYP 50,000-200,000 a year (about US$20-$80 at official rates)</li><li>No official scholarship for foreign students found</li><li>Living costs: not estimated because of conditions</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Arabic proof for Arabic-taught programmes</li></ul>' WHERE slug = 'syria';
UPDATE countries SET why_title = 'Why study in Timor-Leste?', why_body = '<p>Timor-Leste offers Portuguese-taught degrees at UNTL and a few private universities in Dili, with English programmes at some institutions.<ul><li>Portuguese-medium teaching</li><li>Universidade Nacional Timor Lorosa''e (UNTL)</li><li>Low tuition</li><li>Southeast Asian location</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>The study visa is valid for the study period and allows a six-month extension. Sources list a fee of US$50 (statutory summary) or US$80 (FAQ); the official portal is migracao.gov.tl.</p><ul><li>Admission letter from the institution</li><li>Confirm the fee on the immigration portal</li><li>Check the embassy</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Timor-Leste immigration (migracao.gov.tl) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Contact UNTL''s admissions office; international degrees taught in English need a language certificate.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Accounts conflict.</p><ul><li>UNTL: low tuition set by the rector and approved by government (education profile); aggregator: US$100-$500 a year; an MBBS agency page lists about US$6,000 for the first year (commercial)</li><li>Australia Awards window for 2026 study closed in April 2025; China plans an education fund for Timorese students (July 2026)</li><li>Living costs: about US$400-$700 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Portuguese or English proof depending on programme</li></ul>' WHERE slug = 'timor-leste';
UPDATE countries SET why_title = 'Why study in Vatican City?', why_body = '<p>Vatican City has no regular universities within the state itself; students pursue pontifical degrees at the pontifical universities in Rome, under Italian student-visa rules.<ul><li>Pontifical Gregorian University</li><li>Pontifical Urbaniana University</li><li>Pontifical University of St Thomas Aquinas (Angelicum)</li><li>Degrees in theology, philosophy, canon law and related fields</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Non-EU applicants need an entry visa for study in Italy. The Gregorian University issues a pre-enrolment certificate with which you apply at the Italian consulate in your country; a tourist visa cannot be changed into a student visa in Italy.</p><ul><li>Pre-enrolment certificate from the university</li><li>Third-party guide cites proof of at least EUR 10,179.85 a year plus health insurance (Italian Embassy in Washington checklist, 9 July 2026)</li><li>The final decision on visas rests with Italian diplomatic and consular missions</li><li>Italian study-visa procedures are being adapted for 2026-27</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official The Italian consulate and the pontifical university''s International Students Office site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each pontifical university; check requirements with the International Students Office.</p><ul><li>Academic transcripts and certificates</li><li>Language proof (Italian or English per programme)</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Letters of recommendation for some programmes</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Third-party fee tables list Gregorian University fees.</p><ul><li>Gregorian University: about EUR 2,450 a year (Baccalaureate) and EUR 3,080 a year (Licentiate, psychology excepted) per a third-party guide (October 2026); not confirmed on the university page</li><li>Living costs in Rome: about EUR 1,000-1,600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school diploma</li><li><strong>Master''s:</strong> a relevant bachelor''s or baccalaureate degree</li><li><strong>Language:</strong> Italian or English proof depending on programme</li></ul>' WHERE slug = 'vatican-city';
UPDATE countries SET why_title = 'Why study in Yemen?', why_body = '<p>Yemen has public universities such as Sana''a, Aden and Hadhramout, but security conditions are very severe and travel is strongly discouraged.<ul><li>Sana''a University (1970), Aden University (1975)</li><li>Arabic-medium teaching</li><li>Hadhramout University scholarships for students from other countries</li><li>Check current conditions</li></ul></p><p>As of 18 October 2026 the UK and Canada advise against all travel to Yemen (summary). Sana''a airport is closed to commercial flights per a US advisory snippet. This page does not recommend travel.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Yemen does not issue visas at ports of entry; you must get the visa from a Yemeni embassy or consulate before travel, with a letter of acceptance from the institution.</p><ul><li>Letter of acceptance from the Yemeni institution</li><li>Visa from an embassy or consulate in advance</li><li>Limited embassy capacity; check official advice</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Yemeni embassy and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Contact each university''s international office.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Guide estimates only.</p><ul><li>Public universities: about US$80-$320 a year (non-official guide)</li><li>Hadhramout University runs scholarship programmes for students from other countries</li><li>Living costs: about US$200-$400 a month (guide)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Arabic proof for Arabic-taught programmes</li></ul>' WHERE slug = 'yemen';
COMMIT;
